        for (int i = 0; i &lt; _vfxQueue.Count; i++)
        {
            var req = _vfxQueue[i];
            if (req.Anchor != null)
            {
                req.WorldPosition = req.Anchor.position;
                req.WorldRotation = req.Anchor.rotation;
                req.HasWorldPose = true;
                _vfxQueue[i] = req;
            }
        }

        // Hide this screen
        if (_rewardsParent != null) _rewardsParent.SetActive(false);

        // Play VFX
        if (_rewardVFXManager != null &amp;&amp; _vfxQueue.Count &gt; 0)
        {
            _rewardVFXManager.PlayBatch(_vfxQueue);
        }
        _vfxQueue.Clear();

        // Cleanup reward item instances
        if (_rewardItems != null)
        {
            foreach (var rewardItem in _rewardItems)
                if (rewardItem != null) Destroy(rewardItem.gameObject);
            _rewardItems.Clear();
        }

        _seasonPassChest.SetActive(false);

        if(OnTapCallback != null)
        {
            HideThisScreen(true, true);
            _rewardBoxVisibilityController.Hide();
            yield return new WaitForSeconds(2.5f);
            if (_parent != null) _parent.SetActive(false);
            OnTapCallback.Invoke();
        }
        else 
        {
            if (_parent != null) _parent.SetActive(false);
